        if (!pathBlindLegs.contains(id)) {
          expect(
            ifText,
            contains(RegExp(r"needs\.changes\.outputs\.[a-z0-9-]+")),
            reason: 'gh-1551: the guard must be ANDed ON TOP of `$id`\'s '
